const byCode = new Map(COUNTRIES.map((c) => [c.code, c]));

export function getCountry(code: string | undefined): Country | undefined {
  return code ? byCode.get(code) : undefined;
}

/** Localized display name, falling back to English. */
export function countryName(country: Country, locale: CountryLocale): string {
  return country.name[locale] ?? country.name.en;
}
